input.command:
gh api repos/elviskahoro/native/rulesets/25239369 > /tmp/rs.json && python3 - <<'E'
import json
r=json.load(open('/tmp/rs.json'))
for x in r['rules']:
    if x['type']=='required_status_checks':
        for c in x['parameters']['required_status_checks']:
            if c['context']=='pullfrog-approval':
                c['context']='RWX: pullfrog-approval'; c.pop('integration_id',None)
json.dump({k:r[k] for k in ('name','target','enforcement','conditions','rules','bypass_actors')},open('/tmp/rs_new.json','w'))
E
gh api -X PUT repos/elviskahoro/native/rulesets/25239369 --input /tmp/rs_new.json --jq '.rules[]|select(.type=="required_status_checks")|.parameters.required_status_checks'

